import * as Sentry from "@sentry/nextjs/cloudflare";
/* eslint-disable @typescript-eslint/ban-ts-comment */
// @ts-ignore `.open-next/worker.js` is generated by `opennextjs-cloudflare build`.
import handler from "./.open-next/worker.js";

/*
 * The deployed Worker: OpenNext's handler wrapped by Sentry, so server errors and
 * request traces are reported. Next.js catches errors while rendering and logs them
 * instead of throwing, so logged errors are reported too. (Next's instrumentation
 * hook isn't used: its server chunk isn't bundled for Workers.) `next dev` doesn't
 * use this file.
 */
export default Sentry.withSentry(
  (env: { SENTRY_DSN?: string }) => ({
    dsn: env.SENTRY_DSN,
    tracesSampleRate: 0.1,
    integrations: [Sentry.captureConsoleIntegration({ levels: ["error"] })],
  }),
  handler,
);
